from pathlib import Path
import re
import sys

root = Path(sys.argv[1] if len(sys.argv) > 1 else 'public')
overrides = Path(__file__).resolve().parent

# Append V20 styles once.
css_path = root / 'styles.css'
css = css_path.read_text(encoding='utf-8')
extra = (overrides / 'v20_polish.css').read_text(encoding='utf-8')
if 'MING EAGLE V20' not in css:
    css_path.write_text(css + '\n\n' + extra + '\n', encoding='utf-8')


def replace_gallery(page_name: str, snippet: str) -> None:
    path = root / page_name
    text = path.read_text(encoding='utf-8')
    pattern = re.compile(
        r'<section class="section"><div class="wrap"><div class="eyebrow" data-i18n="common\.gallery">REAL PRODUCT HIGHLIGHTS</div>.*?</section>',
        re.S,
    )
    if 'id="real-product-highlights"' in text:
        return
    match = pattern.search(text)
    if not match:
        raise SystemExit(f'V20 highlight section not found in {page_name}')
    text = text[:match.start()] + snippet + text[match.end():]
    path.write_text(text, encoding='utf-8')


