# Curate the first product's creator videos: wider cards and only three live embeds.
p = root / 'silent-basketball.html'
text = p.read_text(encoding='utf-8')
if 'productVideoRail' not in text:
    text = text.replace('class="creatorRail productRail"', 'class="creatorRail productRail productVideoRail"', 1)
    note = '<div class="productVideoNote"><span><b>3 featured creator videos</b> · Wider players for reliable loading on the product page.</span><a href="videos.html#flocked-silent-basketball">See all 16 creator clips →</a></div>'
